#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>
#include <algorithm>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    if (books.empty()) {
        return books.size();
    }

    std::size_t last = books.size();

    #pragma omp parallel
    {
        std::size_t local_last = books.size();

        #pragma omp for nowait
        for (std::size_t i = 0; i < books.size(); ++i) {
            if (books[i].pages < 100) {
                local_last = i;
            }
        }

        #pragma omp critical
        {
            if (local_last != books.size()) {
                if (last == books.size() || local_last > last) {
                    last = local_last;
                }
            }
        }
    }

    return last;
}
